// ---------------------------------------------------------------------------
// tb_lenet_top.v
//
// Runs one full LeNet-5 inference (image -> C1 -> S2 -> C3 -> S4 -> F5 ->
// F6 -> OUT -> ARGMAX) using weight/bias/image ROMs generated by
// scripts/gen_weights.py, and reports the predicted class + cycle count.
//
// NOTE: weights/image here are structural placeholders (deterministic
// pseudo-random, see gen_weights.py), NOT weights exported from the
// trained PyTorch model in the original repo. This testbench verifies
// that the datapath, control FSM, and memory addressing are functionally
// correct end-to-end -- not classification accuracy. Swap in real
// quantized weights (same file format) to test actual accuracy.
// ---------------------------------------------------------------------------
`timescale 1ns/1ps

module tb_lenet_top;

    reg clk, rst_n, start;
    wire busy, class_valid;
    wire [7:0] class_idx;

    integer cycle_count;

    lenet_top #(
        .DATA_W(8), .ACC_W(32), .ADDR_W(16), .SHIFT(4),
        .WEIGHTS_DIR("/home/claude/lenet_npu/sim")
    ) dut (
        .clk(clk), .rst_n(rst_n), .start(start),
        .busy(busy), .class_valid(class_valid), .class_idx(class_idx)
    );

    // 100 MHz clock
    initial clk = 0;
    always #5 clk = ~clk;

    always @(posedge clk) begin
        if (!rst_n) cycle_count <= 0;
        else        cycle_count <= cycle_count + 1;
    end

    initial begin
        $dumpfile("/home/claude/lenet_npu/sim/waves.vcd");
        $dumpvars(0, tb_lenet_top);

        rst_n = 0; start = 0;
        repeat (5) @(posedge clk);
        rst_n = 1;
        @(posedge clk);
        start = 1;

        wait (class_valid == 1'b1);
        @(posedge clk);

        $display("=====================================================");
        $display(" LeNet-5 NPU inference complete");
        $display(" Predicted class index : %0d", class_idx);
        $display(" Total clock cycles    : %0d", cycle_count);
        $display("=====================================================");

        start = 0;
        repeat (5) @(posedge clk);
        $finish;
    end

    // safety timeout
    initial begin
        #200_000_000; // 200 ms sim time
        $display("ERROR: simulation timed out without completing inference");
        $finish;
    end

endmodule
